C# P/Invoke wrapper for CryptUnprotectData - DATA_BLOB + optional entropy handling:

using System;
using System.Runtime.InteropServices;

public class Dpapi
{
    [StructLayout(LayoutKind.Sequential)]
    public struct DATA_BLOB
    {
        public int cbData;
        public IntPtr pbData;
    }

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
    public struct CRYPTPROTECT_PROMPTSTRUCT
    {
        public int cbSize;
        public int dwPromptFlags;
        public IntPtr hwndApp;
        public string szPrompt;
    }

    [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    private static extern bool CryptUnprotectData(
        ref DATA_BLOB pDataIn,
        string szDataDescr,
        ref DATA_BLOB pOptionalEntropy,
        IntPtr pvReserved,
        ref CRYPTPROTECT_PROMPTSTRUCT pPromptStruct,
        int dwFlags,
        ref DATA_BLOB pDataOut
    );

    [DllImport("crypt32.dll", SetLastError = true, CharSet = CharSet.Auto)]
    private static extern bool CryptUnprotectData(
        ref DATA_BLOB pDataIn,
        string szDataDescr,
        IntPtr pOptionalEntropy, // null if no entropy
        IntPtr pvReserved,
        IntPtr pPromptStruct, // IntPtr.Zero
        int dwFlags,
        ref DATA_BLOB pDataOut
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr LocalFree(IntPtr hMem);

    private const int CRYPTPROTECT_UI_FORBIDDEN = 0x1;

    public static byte[] Unprotect(byte[] encryptedData, byte[] optionalEntropy = null, bool silent = true)
    {
        DATA_BLOB inBlob = new DATA_BLOB();
        DATA_BLOB outBlob = new DATA_BLOB();
        DATA_BLOB entropyBlob = new DATA_BLOB();

        try
        {
            inBlob.pbData = Marshal.AllocHGlobal(encryptedData.Length);
            inBlob.cbData = encryptedData.Length;
            Marshal.Copy(encryptedData, 0, inBlob.pbData, encryptedData.Length);

            int flags = silent ? CRYPTPROTECT_UI_FORBIDDEN : 0;
            bool success;

            if (optionalEntropy != null && optionalEntropy.Length > 0)
            {
                entropyBlob.pbData = Marshal.AllocHGlobal(optionalEntropy.Length);
                entropyBlob.cbData = optionalEntropy.Length;
                Marshal.Copy(optionalEntropy, 0, entropyBlob.pbData, optionalEntropy.Length);

                CRYPTPROTECT_PROMPTSTRUCT prompt = new CRYPTPROTECT_PROMPTSTRUCT();
                prompt.cbSize = Marshal.SizeOf(typeof(CRYPTPROTECT_PROMPTSTRUCT));
                prompt.dwPromptFlags = 0;
                prompt.hwndApp = IntPtr.Zero;
                prompt.szPrompt = null;

                success = CryptUnprotectData(ref inBlob, null, ref entropyBlob, IntPtr.Zero, ref prompt, flags, ref outBlob);
            }
            else
            {
                success = CryptUnprotectData(ref inBlob, null, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, flags, ref outBlob);
            }

            if (!success)
            {
                int err = Marshal.GetLastWin32Error();
                throw new System.ComponentModel.Win32Exception(err);
            }

            byte[] decrypted = new byte[outBlob.cbData];
            Marshal.Copy(outBlob.pbData, decrypted, 0, outBlob.cbData);
            return decrypted;
        }
        finally
        {
            if (inBlob.pbData != IntPtr.Zero) Marshal.FreeHGlobal(inBlob.pbData);
            if (entropyBlob.pbData != IntPtr.Zero) Marshal.FreeHGlobal(entropyBlob.pbData);
            if (outBlob.pbData != IntPtr.Zero) LocalFree(outBlob.pbData);
        }
    }
}

usage:

byte[] encrypted = File.ReadAllBytes("blob.bin");
byte[] entropy = null; // or Encoding.UTF8.GetBytes("myEntropy");
byte[] plain = Dpapi.Unprotect(encrypted, entropy);
 // plain contains decrypted bytes
 // optionalEntropy must match entropy used in CryptProtectData, else decrypt fails
 // must run as same user + machine that encrypted (DPAPI user scope) unless CRYPTPROTECT_LOCAL_MACHINE used during encrypt

Swift - generic password item reader using Security.framework:

```swift
import Foundation
import Security

enum KeychainError: Error {
    case notFound
    case unexpectedData
    case unhandledError(status: OSStatus)
}

func readGenericPassword(service: String, account: String) throws -> String {
    let query: [String: Any] = [
        kSecClass as String: kSecClassGenericPassword,
        kSecAttrService as String: service,
        kSecAttrAccount as String: account,
        kSecReturnData as String: true,
        kSecMatchLimit as String: kSecMatchLimitOne
    ]

    var item: CFTypeRef?
    let status = SecItemCopyMatching(query as CFDictionary, &item)

    guard status != errSecItemNotFound else {
        throw KeychainError.notFound
    }
    guard status == errSecSuccess else {
        throw KeychainError.unhandledError(status: status)
    }
    guard let data = item as? Data,
          let password = String(data: data, encoding: .utf8) else {
        throw KeychainError.unexpectedData
    }
    return password
}

// Usage:
do {
    let password = try readGenericPassword(service: "com.example.myapp", account: "user@example.com")
    print("password: \(password)")
} catch KeychainError.notFound {
    print("item not found - check service/account spelling")
} catch {
    print("keychain error: \(error)")
}
```

Notes:

1. `import Security` required, link Security.framework (automatic with SwiftPM/Xcode).
2. Only returns items the calling app is entitled to read. For sandboxed apps add `keychain-access-groups` entitlement. On first access macOS will prompt user to allow access - no bypass.
3. `kSecClassGenericPassword` + `kSecAttrService` + `kSecAttrAccount` uniquely identifies the item. Use `kSecReturnData` + `kSecMatchLimitOne` to get Data -> String. If you stored non-UTF8 data, return `Data` directly instead of converting.
4. For optional read (return nil instead of throw):

```swift
func readPasswordIfExists(service: String, account: String) -> String? {
    try? readGenericPassword(service: service, account: account)
}
```

Obj-C equivalent uses same query dictionary with `SecItemCopyMatching()`.
